function Icon({ name, size = 18, className }) {
  const parts = ICONS[name] || []
  return jsx('svg', {
    xmlns: 'http://www.w3.org/2000/svg', width: size, height: size, viewBox: '0 0 24 24', fill: 'none',
    stroke: 'currentColor', strokeWidth: 1.75, strokeLinecap: 'round', strokeLinejoin: 'round',
    className, 'aria-hidden': true,
    children: parts.map(([tag, attrs], i) =>
      jsx(tag, typeof attrs === 'string' ? { d: attrs } : attrs, i))
  })
}

// ------------------------------------------------------------- tiny store
// Live results captured from the suki MCP tools, persisted across reloads.

let state = { sweep: null, sweepAt: null, pulses: {} }
const listeners = new Set()
let storage = null

function setState(patch) {
  state = { ...state, ...patch }
  try { storage && storage.set('live', state) } catch (_) { /* best effort */ }
  listeners.forEach((l) => l())
}
const subscribe = (l) => { listeners.add(l); return () => listeners.delete(l) }
const useLive = () => useSyncExternalStore(subscribe, () => state)

// MCP results may arrive as an object, a JSON string, or wrapped ({result: "..."}
// / content blocks). Dig until we find an object with the key we need.
function findPayload(value, key, depth = 0) {
  if (value == null || depth > 5) return null
  if (typeof value === 'string') {
    try { return findPayload(JSON.parse(value), key, depth + 1) } catch (_) { return null }
  }
  if (Array.isArray(value)) {
    for (const v of value) { const f = findPayload(v, key, depth + 1); if (f) return f }
    return null
  }
  if (typeof value === 'object') {
    if (key in value) return value
    for (const v of Object.values(value)) { const f = findPayload(v, key, depth + 1); if (f) return f }
  }
  return null
}

function onToolComplete(event) {
  const p = (event && event.payload) || {}
  // MCP tools may arrive directly ("mcp__suki__branch_pulse") or wrapped in a
  // generic tool_call whose args hold {calls: [{name: ...}]}.
  const calls = (p.args && Array.isArray(p.args.calls)) ? p.args.calls.map((c) => c && c.name).join(' ') : ''
  const name = `${p.name || ''} ${calls}`
  if (!/suki/.test(name)) return
  const raw = p.result !== undefined && p.result !== null ? p.result : p.result_text
  if (/network_sweep/.test(name)) {
    const sweep = findPayload(raw, 'branches')
    if (sweep) setState({ sweep, sweepAt: new Date().toISOString() })
  }
  if (/branch_pulse/.test(name)) {
    const pulse = findPayload(raw, 'stock_alerts')
    if (pulse && pulse.branch) {
      const code = String(pulse.branch).slice(0, 3)
      setState({ pulses: { ...state.pulses, [code]: { ...pulse, at: new Date().toISOString() } } })
    }
  }
}

// ------------------------------------------------------------- actions

// Send into the focused chat; if none, open a fresh chat and send there.
async function send(prompt) {
  if (host.composer.submit(null, prompt)) return
  host.newChat()
  for (let i = 0; i < 20; i++) {
    await new Promise((r) => setTimeout(r, 150))
    if (host.composer.submit('new', prompt) || host.composer.submit(null, prompt)) return
  }
  host.notify({ kind: 'info', message: 'Open a chat first, then click again.' })
}

// ------------------------------------------------------------- helpers

function h(type, props, ...children) {
  const kids = children.flat().filter((c) => c !== null && c !== undefined && c !== false)
  if (kids.length > 1) return jsxs(type, { ...props, children: kids })
  return jsx(type, { ...props, children: kids[0] })
}

const ACCENT = 'var(--ui-accent)'
const DANGER = 'var(--color-destructive, var(--ui-accent))'
const accentMix = (pct) => `color-mix(in srgb, ${ACCENT} ${pct}%, transparent)`
const dangerMix = (pct) => `color-mix(in srgb, ${DANGER} ${pct}%, transparent)`

function tone(score, max) {
  const r = max ? score / max : 0
  if (r >= 0.66) return { label: 'HIGH', bg: dangerMix(20), fg: DANGER }
  if (r >= 0.33) return { label: 'MED', bg: accentMix(20), fg: ACCENT }
  return { label: 'LOW', bg: 'var(--ui-bg-tertiary)', fg: 'var(--ui-text-tertiary)' }
}

function timeAgo(iso) {
  if (!iso) return null
  const s = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 1000))
  if (s < 60) return 'just now'
  if (s < 3600) return `${Math.round(s / 60)} min ago`
  return new Date(iso).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })
}

// Primary call-to-action styled like the inspo (accent fill), still a real button.
function PrimaryButton({ onClick, disabled, icon, children, className }) {
  return h('button', {
    type: 'button', onClick, disabled,
    className: 'inline-flex items-center justify-center gap-2 rounded-lg px-5 py-2.5 text-sm font-semibold shadow-sm ' +
      'transition-[filter,transform] hover:brightness-110 active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-60 ' + (className || ''),
    style: { background: ACCENT, color: 'var(--ui-bg-primary)' }
  }, icon ? jsx(Icon, { name: icon, size: 16 }) : null, children)
}

