function AskBox({ branch, busy, compact }) {
  const [text, setText] = useState('')
  const submit = () => {
    const q = text.trim()
    if (!q) return
    send(`Use the ${SKILL} skill for ${branch.code} (${branch.name}): ${q}`)
    setText('')
  }
  return h('div', { className: 'flex gap-2' },
    h('label', {
      className: 'flex min-w-0 flex-1 items-center gap-2 rounded-xl border border-(--ui-stroke-secondary) bg-(--ui-bg-card) px-3 ' +
        (compact ? 'py-1.5' : 'py-3') + ' focus-within:border-(--ui-accent)'
    },
      h('span', { className: 'text-(--ui-text-tertiary)' }, jsx(Icon, { name: 'chat', size: 18 })),
      jsx('input', {
        value: text,
        disabled: busy,
        placeholder: compact ? `Ask Kuya about ${branch.code}…` : `Ask Kuya about ${branch.code}…   e.g. ubos na ba ang bottled water?`,
        onChange: (e) => setText(e.target.value),
        onKeyDown: (e) => { if (e.key === 'Enter') submit() },
        className: 'min-w-0 flex-1 bg-transparent text-sm text-(--ui-text-primary) placeholder:text-(--ui-text-tertiary) outline-none'
      })),
    jsx(PrimaryButton, { disabled: busy || !text.trim(), onClick: submit, icon: 'send', children: 'Ask' })
  )
}

function PulseView({ pulse }) {
  const alerts = (pulse.stock_alerts || []).slice(0, 5)
  const gaps = (pulse.shift_gaps_next_2_days || []).slice(0, 4)
  const t = pulse.tickets || {}
  const d = pulse.deliveries_last_7d
  return h('div', { className: 'rounded-xl border border-(--ui-stroke-secondary) bg-(--ui-bg-card) p-4', style: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: 20 } },
    h('div', { className: 'flex flex-col gap-2' },
      h('div', { className: 'flex items-center justify-between text-xs font-semibold text-(--ui-text-secondary)' },
        h('span', null, `Stock alerts · ${pulse.stock_alerts_total || 0} total, ${pulse.out_of_stock || 0} out`),
        h('span', { className: 'font-normal text-(--ui-text-tertiary)' }, `live · ${timeAgo(pulse.at)}`)),
      alerts.length ? alerts.map((s) =>
        h('div', { key: s.sku, className: 'flex items-center justify-between gap-2 text-xs' },
          h('span', { className: 'truncate' }, s.product),
          h('span', { className: 'flex shrink-0 items-center gap-1.5' },
            h('span', { className: 'tabular-nums text-(--ui-text-tertiary)' }, `${s.on_hand} on hand`),
            s.open_po
              ? jsx(Chip, { children: s.duplicate_open_pos ? `⚠️ ${s.duplicate_open_pos + 1} POs` : 'PO open' })
              : jsx(Chip, { bg: dangerMix(18), color: DANGER, children: 'no PO' }))
        )) : h('div', { className: 'text-xs text-(--ui-text-tertiary)' }, 'No stock alerts 🎉')
    ),
    h('div', { className: 'flex flex-col gap-2' },
      h('div', { className: 'text-xs font-semibold text-(--ui-text-secondary)' }, 'Staffing · next 2 days'),
      gaps.length ? gaps.map((g) =>
        h('div', { key: g.date + g.block, className: 'flex items-center justify-between text-xs' },
          h('span', null, `${g.date.slice(5)} · ${g.block}`),
          jsx(Chip, { bg: accentMix(18), color: ACCENT, children: `${g.scheduled}/${g.target} · short ${g.short_by}` }))
      ) : h('div', { className: 'text-xs text-(--ui-text-tertiary)' }, 'Fully staffed ✅'),
      h('div', { className: 'mt-1 text-xs font-semibold text-(--ui-text-secondary)' }, 'Customers'),
      h('div', { className: 'flex flex-wrap gap-1' },
        jsx(Chip, { children: `💬 ${t.open_tickets || 0} open` }),
        jsx(Chip, { bg: t.never_answered ? dangerMix(18) : undefined, color: t.never_answered ? DANGER : undefined, children: `🙈 ${t.never_answered || 0} never answered` }),
        jsx(Chip, { children: `⏰ ${t.older_than_7d || 0} > 7 days` }),
        typeof d === 'object' && d ? jsx(Chip, { children: `🛵 ${(d.late || 0)} late · ${(d.failed || 0)} failed` }) : jsx(Chip, { children: '🛵 no delivery' }))
    )
  )
}

function HowItWorks() {
  const steps = ['This page / Telegram', 'kuya-hermes-ops skill', 'suki MCP tools', 'Suki Mart store.db']
  return h('div', { className: 'flex items-center gap-4 rounded-xl border border-dashed border-(--ui-stroke-secondary) p-4' },
    h('span', { className: 'text-(--ui-text-tertiary)' }, jsx(Icon, { name: 'gear', size: 22 })),
    h('div', { className: 'flex flex-col gap-1' },
      h('div', { className: 'text-[0.6875rem] font-semibold uppercase tracking-[0.12em] text-(--ui-text-tertiary)' }, 'How it works'),
      h('div', { className: 'flex flex-wrap items-center gap-2 text-sm text-(--ui-text-secondary)' },
        steps.map((s, i) => [h('span', { key: s }, s), i < steps.length - 1 ? h('span', { key: `a${i}`, className: 'text-(--ui-text-tertiary)' }, '→') : null])))
  )
}

// ------------------------------------------------------------- page

function HqPage() {
  const busy = useValue(host.state.busy)
  const gateway = useValue(host.state.gateway)
  const live = useLive()
  const [code, setCode] = useState(() => (live.sweep && live.sweep.worst) || 'ALB')
  const branch = BRANCHES.find((b) => b.code === code) || BRANCHES[0]
  const rows = (live.sweep && live.sweep.branches) || []
  const byCode = Object.fromEntries(rows.map((r, i) => [r.branch, { ...r, rank: i + 1 }]))
  const max = Math.max(1, ...rows.map((r) => Number(r.risk_score) || 0))

  // Layout-critical styles are inline: the host app only ships the Tailwind
  // classes its own code uses, so max-width / custom grid utilities may not exist.
  return h('div', { className: 'h-full overflow-auto', style: { height: '100%', overflow: 'auto' } },
    h('div', {
      className: 'flex flex-col text-sm',
      style: { maxWidth: 1080, margin: '0 auto', padding: '32px clamp(20px, 5vw, 64px) 48px', display: 'flex', flexDirection: 'column', gap: 24 }
    },
      jsx(Header, { gateway, busy }),
      jsx(SweepCard, { busy, live }),
      rows.length ? jsx(Kpis, { sweep: live.sweep }) : null,
      h('div', { className: 'flex flex-col gap-3' },
        jsx(SectionLabel, {
          children: 'Branches',
          right: rows.length
            ? h('span', { className: 'text-xs text-(--ui-text-tertiary)' }, `risk scores from last sweep · ${timeAgo(live.sweepAt)}`)
            : h('span', { className: 'text-xs text-(--ui-text-tertiary)' }, 'run a sweep to see live risk scores')
        }),
        h('div', { className: 'grid', style: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: 12 } },
          BRANCHES.map((b) => jsx(BranchCard, {
            branch: b, selected: b.code === code, onSelect: setCode,
            risk: byCode[b.code], rank: byCode[b.code] && byCode[b.code].rank, max
          }, b.code)))
      ),
      h('div', { className: 'flex flex-col gap-3' },
        jsx(SectionLabel, { children: `${branch.code} · ${branch.name}` }),
        h('div', { className: 'grid', style: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(240px, 1fr))', gap: 12 } },
          BRANCH_ACTIONS.map((a) => jsx(ActionCard, { action: a, branch, busy }, a.id))),
        jsx(AskBox, { branch, busy }),
        live.pulses[code] ? jsx(PulseView, { pulse: live.pulses[code] }) : null
      ),
      jsx(HowItWorks, {})
    )
  )
}

// ------------------------------------------------------------- side pane

function HqPane() {
  const busy = useValue(host.state.busy)
  const live = useLive()
  const [code, setCode] = useState('ALB')
  const branch = BRANCHES.find((b) => b.code === code) || BRANCHES[0]
  const top = ((live.sweep && live.sweep.branches) || []).slice(0, 3)

  return h('div', { className: 'flex h-full flex-col gap-3 overflow-auto p-3 text-sm' },
    h('div', { className: 'flex items-center gap-2.5' },
      h('img', { src: MASCOT, alt: 'Kuya Hermes', className: 'rounded-full object-cover', style: { width: 40, height: 40, borderRadius: 999, objectFit: 'cover', background: accentMix(18) } }),
      h('div', null,
        h('div', { className: 'font-semibold' }, 'Kuya Hermes HQ'),
        h('div', { className: 'text-xs text-(--ui-text-tertiary)' }, busy ? 'Kuya is working…' : 'Suki Mart branch ops'))),
    jsx(PrimaryButton, { disabled: busy, icon: 'fullSweep', onClick: () => send(SWEEP_PROMPT), children: 'Run full sweep' }),
    top.length ? h('div', { className: 'flex flex-col gap-1' },
      h('div', { className: 'text-[0.6875rem] font-semibold uppercase tracking-wide text-(--ui-text-tertiary)' }, `Top risk · ${timeAgo(live.sweepAt)}`),
      top.map((r, i) =>
        h('button', {
          key: r.branch, type: 'button', onClick: () => setCode(r.branch),
          className: 'flex items-center justify-between rounded-lg border border-(--ui-stroke-secondary) px-2 py-1.5 text-xs hover:bg-(--ui-bg-secondary)'
        },
          h('span', null, `${i === 0 ? '🔥' : `#${i + 1}`} ${r.branch} · ${nameOf(r.branch)}`),
          h('span', { className: 'font-semibold tabular-nums' }, String(r.risk_score))))
    ) : null,
    jsx('select', {
      value: code,
      onChange: (e) => setCode(e.target.value),
      className: 'rounded-lg border border-(--ui-stroke-secondary) bg-(--ui-bg-input) px-2 py-1.5 text-sm text-(--ui-text-primary)',
      children: BRANCHES.map((b) => jsx('option', { value: b.code, children: `${b.code} · ${b.name}` }, b.code))
    }),
    BRANCH_ACTIONS.map((a) => jsx(ActionCard, { action: a, branch, busy }, a.id)),
    jsx(AskBox, { branch, busy, compact: true }),
    h('button', {
      type: 'button', onClick: () => host.navigate(PAGE_PATH),
      className: 'mt-1 text-left text-xs underline-offset-2 hover:underline', style: { color: ACCENT }
    }, 'Open full HQ dashboard →')
  )
}

// ------------------------------------------------------------- register

export default {
  id: PLUGIN_ID,
  name: 'Kuya Hermes HQ',
  register(ctx) {
    storage = ctx.storage
    try {
      const saved = storage.get('live', null)
      if (saved && typeof saved === 'object') state = { ...state, ...saved }
    } catch (_) { /* first run or storage unavailable */ }

    ctx.onEvent('tool.complete', onToolComplete)

    ctx.registerMany([
      { id: 'page', area: ROUTES_AREA, data: { path: PAGE_PATH }, render: () => jsx(HqPage, {}) },
      { id: 'nav', area: SIDEBAR_NAV_AREA, data: { path: PAGE_PATH, label: 'Kuya Hermes HQ', codicon: 'pulse' } },
      {
        id: 'pane', area: PANES_AREA, title: 'Kuya Hermes',
        data: { placement: 'right', width: '300px' },
        render: () => jsx(HqPane, {})
      },
      {
        id: 'sweep', area: PALETTE_AREA,
        data: { id: `${PLUGIN_ID}.sweep`, label: 'Kuya Hermes: Run full sweep', keywords: ['suki', 'sweep', 'kuya', 'branch'], run: () => send(SWEEP_PROMPT) }
      },
      {
        id: 'open', area: PALETTE_AREA,
        data: { id: `${PLUGIN_ID}.open`, label: 'Kuya Hermes: Open HQ dashboard', keywords: ['suki', 'kuya', 'hq'], run: () => host.navigate(PAGE_PATH) }
      }
    ])
  }
}
